/*
 * Chapters 5–12 are intentionally kept in a separate editorial file while
 * they are expanded. Each entry carries the concrete mechanism, failure mode,
 * boundary and experiment for its topic; the renderer only gives those facts
 * a consistent four-section book shape.
 */
import type { Block } from "@/lib/study/types";
import type { ContentChapter, ContentExercise, ContentCard } from "./types";
import { JAVASCRIPT_ERRORS_CHAPTER } from "./javascriptErrorsChapter";
import { JAVASCRIPT_EVENT_LOOP_CHAPTER } from "./javascriptEventLoopChapter";
import { JAVASCRIPT_DOM_CHAPTER } from "./javascriptDomChapter";
import { JAVASCRIPT_DOMAIN_CHAPTER } from "./javascriptDomainChapter";
import { JAVASCRIPT_ITERATION_CHAPTER } from "./javascriptIterationChapter";
import { JAVASCRIPT_PERFORMANCE_CHAPTER } from "./javascriptPerformanceChapter";
import { JAVASCRIPT_TESTING_CHAPTER } from "./javascriptTestingChapter";
import { JAVASCRIPT_PROJECT_CHAPTER } from "./javascriptProjectChapter";

type Chapter = { title: string; level: ContentChapter["level"]; concepts: [string, string, string, string]; editorial: [string, string, string, string]; mechanism: string; incident: string; experiment: string; labId?: "ophis" };

const chapters: Chapter[] = [
  { title: "Erros e contratos assíncronos", level: "intermediario", concepts: ["exceções, causa e fronteiras", "Promise e propagação de rejeição", "cancelamento com AbortSignal", "idempotência e retry"], editorial: ["Erro de validação, erro de infraestrutura e resultado desconhecido são estados diferentes. Um cartão recusado pode ser informado imediatamente; um timeout depois de enviar cobrança não prova que nada ocorreu. Preserve `cause`, traduza para um código de domínio na borda e nunca exponha detalhes internos como mensagem de produto.", "Uma função `async` não torna o fluxo paralelo por magia: ela devolve imediatamente uma Promise e cada `await` suspende apenas aquela continuação. `return await` só é útil quando a função precisa observar ou traduzir a rejeição; de outro modo, retornar a Promise preserva o mesmo resultado com menos uma camada.", "Abortar um fetch encerra o interesse do consumidor, não desfaz uma escrita já aceita pelo servidor. O handler deve distinguir `AbortError` de falha operacional e impedir que uma resposta antiga atualize estado já substituído. Quem cria o `AbortController` é responsável por abortá-lo no cleanup.", "Retry seguro precisa de condição explícita: operação idempotente, chave persistida ou estado que consulta o resultado anterior. Repetir POST de reserva sem chave pode duplicar efeito; repetir GET pode mascarar indisponibilidade. Backoff, limite e telemetria pertencem ao contrato, não a um loop infinito."], mechanism: "`throw` interrompe a pilha síncrona; em função async transforma-se em Promise rejeitada. `await` relança rejeição no ponto de suspensão, enquanto `Promise.all` falha cedo e pode deixar operações irmãs em andamento.", incident: "timeout de pagamento tratado como falha certa, seguido de retry que cobra duas vezes porque o primeiro pedido já chegou ao provedor", experiment: "simular Promise rejeitada, abortar fetch, repetir o mesmo comando com chave de idempotência e conferir causa no erro" },
  { title: "Event loop, microtasks e coordenação", level: "intermediario", concepts: ["pilha, tasks e microtasks", "async/await e ordem de continuação", "concorrência limitada", "renderização e trabalho cooperativo"], editorial: ["JavaScript executa uma pilha por vez, mas o host agenda trabalho para depois. Timer com zero não significa agora; significa uma task elegível quando a pilha e microtasks anteriores terminarem. Esse detalhe explica por que uma função CPU-intensiva congela interação mesmo sem bloquear rede.", "A continuação depois de `await` é microtask. Assim, um `then` pode observar estado antes de timer pendente. Use essa ordem para projetar testes determinísticos: crie a Promise controlada, resolva-a, esvazie microtasks e só então avance relógio falso. Nunca dependa de atraso arbitrário para sincronizar teste.", "`Promise.all` inicia tudo de uma vez e é correto apenas quando independência e capacidade permitem. Pool limita recursos: mantém N Promises ativas, inicia outra ao liberar vaga e escolhe se erro cancela fila ou vira resultado. Concorrência é política de produto, não detalhe do array.", "Pintura só ocorre quando o runtime devolve controle ao host. Divida trabalho pesado em blocos mensuráveis, cancele bloco que ficou obsoleto e priorize entrada do usuário. `queueMicrotask` não resolve responsividade: uma cadeia sem fim de microtasks pode impedir a próxima pintura."], mechanism: "callbacks de Promise e `queueMicrotask` entram na fila de microtasks; timers e eventos entram como tasks. Depois de uma task, o runtime esvazia microtasks antes de renderizar ou buscar a próxima task.", incident: "cadeia ilimitada de microtasks impede pintura; dez mil requisições em `Promise.all` derrubam limite do serviço externo", experiment: "registrar ordem de `console.log`, timer e Promise; aplicar pool de três operações e medir que nenhuma quarta inicia antes de vaga" },
  { title: "DOM, eventos e acessibilidade", level: "intermediario", concepts: ["árvore DOM e atualização", "propagação, delegação e cleanup", "formulário, validação e foco", "semântica, teclado e leitor de tela"], editorial: ["DOM é estado observável, não a fonte da regra. Guarde no modelo a linha do carrinho, aplique transição no modelo e renderize a representação correspondente; ler texto de um elemento para descobrir o total torna validação, internacionalização e teste frágeis. Atualização mínima é otimização posterior, não licença para mutação escondida.", "Delegação instala um listener no ancestral estável e encontra o alvo por `closest`; isso atende itens criados depois sem listener por linha. Porém o ancestral também recebe cliques de elementos aninhados: valide escopo e remova o listener no mesmo ciclo que o criou. O erro comum é remount dobrar callbacks e efeitos.", "Validação HTML resolve tipo, obrigatório e alguns limites, mas a regra de domínio ainda precisa validar no servidor. Ao rejeitar, conecte mensagem por `aria-describedby`, marque `aria-invalid` e mova foco de maneira previsível. Não limpe valor digitado nem anuncie a mesma falha duas vezes por canais concorrentes.", "Preferir `button`, `label`, `input` e `dialog` preserva teclado e semântica. Uma div clicável exige tabIndex, Enter/Espaço, papel e estado — e ainda é fácil errar. Modal precisa devolver foco ao gatilho, impedir navegação de fundo e usar título/descrição anunciáveis."], mechanism: "evento percorre captura, alvo e bubbling; `event.target` é origem e `currentTarget` é listener. Elemento nativo fornece semântica, foco e teclado que uma div com click não recria automaticamente.", incident: "listener duplicado após remount envia duas compras; modal visual não prende foco e leitor de tela continua navegando página de fundo", experiment: "delegar clique por `closest`, desmontar listener, submeter formulário só por teclado e inspecionar foco após erro" },
  { title: "Classes, políticas e evolução de domínio", level: "intermediario", concepts: ["encapsulamento e invariantes", "composição de políticas", "serialização e fronteiras", "evolução sem quebrar consumidores"], editorial: ["Encapsular não é esconder todos os campos; é impedir transição impossível. Se saldo nunca pode ser negativo, nenhum método público deve aceitar retirada que atravesse zero. Campo privado protege acesso casual, mas invariável vive na validação de cada transição e nos testes que provam rejeição.", "Herança descreve substituição estável, não uma forma curta de combinar descontos. Política composta recebe dados claros e devolve decisão, permitindo testar frete, cupom e fidelidade isoladamente. Se subclasses acumulam flags para ordem e compatibilidade, a variação pertence a objetos de política, não à árvore de tipos.", "JSON transporta dados, não identidade de instância. Ao desserializar, método, símbolo e protótipo não retornam automaticamente; um DTO precisa atravessar factory que valida versão e reconstitui comportamento. Nunca aceite objeto de rede como entidade de domínio sem verificar seus campos.", "Evoluir contrato pede compatibilidade deliberada: adicione campo opcional, migre produtor e consumidor, só então remova formato antigo. Versione persistência e traduza na borda. Mudar método público para exigir novo argumento sem adaptador transforma atualização local em quebra distante."], mechanism: "campo privado `#saldo` só é acessível no corpo da classe; JSON serializa dados próprios e perde métodos/protótipos; políticas injetadas variam comportamento sem multiplicar subclasses.", incident: "objeto de domínio vindo de JSON é tratado como instância e método não existe; herança de desconto cria combinação impossível de cupom, fidelidade e frete", experiment: "reidratar DTO por factory, trocar policy de preço em teste e provar que estado inválido não atravessa método público" },
  { title: "Iteração, generators e streams", level: "avancado", concepts: ["iterável, iterador e protocolo", "generator e lazy evaluation", "async iteration e cancelamento", "streams e backpressure"], editorial: ["Iterável promete produzir valores; iterator é a máquina que mantém posição. Array pode ser iterado mais de uma vez porque cada chamada cria iterator novo; generator já obtido é consumível. Projetar API exige dizer qual dos dois se entrega, pois guardar iterator compartilhado transforma segunda leitura em surpresa silenciosa.", "Generator interrompe execução em `yield`, preservando variáveis locais sem construir coleção inteira. Isso é lazy evaluation útil para paginação, lotes e busca potencialmente longa. Não é paralelismo: cada próximo valor avança uma única computação. Feche generator quando abandonar cedo para executar `finally` e liberar recurso associado.", "`for await...of` consome valores que chegam no tempo e propaga erro do produtor. Cancelamento precisa viajar até a fonte: quebrar o laço só interrompe consumidor se o iterator implementa `return`; para rede ou stream, associe AbortSignal e trate encerramento como caminho normal, não erro invisível.", "Backpressure é contrato entre velocidade de produção e consumo. Acumular chunks em array transfere limite para memória; pipeline deve pausar origem ou aguardar drain. Meça tamanho de buffer e interrompa cedo ao encontrar resposta. Stream não é apenas sintaxe diferente para array grande."], mechanism: "iterável implementa `[Symbol.iterator]`; iterator produz `{ value, done }`; generator pausa em `yield`. Stream precisa respeitar backpressure: produtor deve desacelerar quando consumidor não drena buffer.", incident: "ler arquivo inteiro em memória para processar milhões de linhas; generator de uso único reutilizado e retorna vazio silenciosamente", experiment: "implementar iterator manual, interromper `for await`, usar pipeline de stream e observar que chunk não cresce sem limite" },
  { title: "Performance, memória e profiling", level: "avancado", concepts: ["medição e flamegraph", "complexidade e estruturas", "garbage collection e leaks", "bundle, parsing e custo de interface"], editorial: ["Comece com pergunta e métrica: qual interação está lenta, em qual dispositivo e qual orçamento é aceitável. Flamegraph aponta onde amostras passaram tempo, não prova causalidade sozinho. Compare antes/depois sob entrada equivalente; sem baseline, uma otimização pode apenas deslocar custo ou piorar caso comum.", "Complexidade aparece com volume. Procurar produto por `find` dentro de cada linha faz trabalho proporcional a linhas vezes catálogo; índice Map desloca custo para construção e dá lookup por chave. Escolha estrutura pela operação dominante, valide memória e mantenha um único owner para não criar índices divergentes.", "GC só coleta o que ficou inalcançável. Listener global, timer, cache sem expiração e closure que captura view mantêm referências vivas apesar de remover DOM. Heap snapshot é comparação: tire baseline, repita navegação, force cenário e encontre caminho retentor antes de atribuir culpa ao coletor.", "Bundle custa download, parse e execução; adiar editor raro melhora primeira interação apenas se o código não é importado por caminho estático. Meça waterfall e CPU, divida fronteira de recurso opcional e modele loading/erro. Não transforme cada função em chunk: requisições e coordenação também têm custo."], mechanism: "profiling amostra pilha e mede custo real; GC libera objeto inalcançável, não objeto que listener, closure ou cache ainda referencia; bundle também cobra parse e execução antes da primeira interação.", incident: "otimização de microsegundo deixa busca O(n²) intacta; listener global retém árvore removida e memória cresce a cada navegação", experiment: "comparar Map contra busca linear em escala, tirar heap snapshot antes/depois de cleanup e medir chunk adiado no carregamento" },
  { title: "Testes, contratos e fronteiras", level: "avancado", concepts: ["unidade e propriedade", "integração e adaptadores", "mocks, fakes e tempo", "contrato, regressão e CI"], editorial: ["Teste unitário deve tornar regra barata de mudar: dados simples entram, resultado ou erro observável sai. Propriedade complementa exemplos ao variar entrada e afirmar invariante, como total não negativo ou estoque nunca abaixo de zero. Evite testar implementação privada; isso congela refactor sem aumentar confiança.", "Integração valida tradução na fronteira: SQL, HTTP, serialização ou fila. Rode contra ambiente controlado e limpe estado para não confundir dados anteriores com resultado. Teste de adaptador não precisa cobrir toda aplicação, mas deve provar formato, erro e transação que mock local não consegue representar.", "Fake é implementação pequena com comportamento relevante; mock registra colaboração e stub devolve resposta fixa. Se mock repete algoritmo de produção, ambos podem errar juntos. Injete relógio, aleatório e rede para tornar tempo e falha reproduzíveis; não use espera real para esperar promessa.", "Contrato entre produtor e consumidor merece teste compartilhado, principalmente ao trocar gateway ou versão. Cada regressão recebe caso mínimo que falhava, não só snapshot novo. CI deve separar testes rápidos e integração, registrar artefatos e falhar por regra real — cobertura é sinal auxiliar, não aprovação automática."], mechanism: "teste unitário observa regra pura; integração observa adaptador real em limite controlado; fake preserva comportamento simplificado e mock verifica colaboração. Relógio e rede devem ser controláveis para cenário determinístico.", incident: "mock copia lógica de produção e o teste passa mesmo com adaptador quebrado; snapshot aprova saída errada porque ninguém afirma invariante", experiment: "criar property test para total nunca negativo, rodar contrato contra fake e real, congelar relógio e reproduzir regressão em CI" },
  { title: "Projeto integrador: estado observável", level: "avancado", concepts: ["reducer e invariantes", "fila, histórico e undo", "persistência e concorrência", "instrumentação e laboratório"], editorial: ["Reducer transforma evento em próximo estado e concentra invariantes. Evento precisa carregar intenção e identidade, não um estado pronto para substituir. Ao rejeitar reserva sem estoque, devolva motivo explícito e mantenha snapshot anterior; mutar em lugar torna histórico e replay impossíveis de confiar.", "Histórico pode guardar ações para replay ou snapshots para undo rápido; ambos precisam de escopo. Undo local não pode desfazer confirmação já persistida por outra sessão. Modele quais eventos são reversíveis, qual compensação externa existe e quando limpar fila após checkpoint; botão não é especificação suficiente.", "Persistência concorrente pede versão ou operação condicional. Cliente envia versão lida, servidor aceita somente se ainda corresponde e devolve conflito com estado atual. Isso não é detalhe de banco: a interface precisa comunicar atualização perdida e permitir reconciliação, em vez de fingir que último clique sempre vence.", "Instrumente transição com nome, duração e resultado, nunca com dados sensíveis crus. O laboratório deve permitir reproduzir sequência, injetar evento inválido e mostrar invariante atingida. Telemetria útil liga incidente a evento e versão; log ruidoso sem correlação apenas esconde a falha."], mechanism: "reducer recebe estado e evento e devolve próximo estado; histórico guarda snapshots/ações; persistência condicional protege versão; telemetria mede transição, não dados sensíveis brutos.", incident: "undo reaplica estado compartilhado e desfaz compra de outra sessão; cliente confirma reserva sem checar versão e perde última unidade", experiment: "executar sequência de eventos no Lab Ophis, gerar estado inválido deliberadamente, verificar reducer rejeita e rastrear cada transição" , labId: "ophis" },
];

function dense(chapter: Chapter, topic: string, slot: string, order: number): Block {
  const { title } = chapter;
  return { kind: "prose", md: [
    `Em **${title}**, ${topic} não é uma API isolada: é uma decisão de execução que define o que o sistema consegue prometer depois de receber uma entrada. A primeira tarefa é separar mecanismo, regra de domínio e efeito de infraestrutura. O mecanismo descreve o que JavaScript e o host fazem; a regra descreve o estado que o produto aceita; o efeito comunica ou persiste a decisão. Quando essas camadas aparecem na mesma função sem contrato, uma falha de rede, de tempo ou de tipo se torna indistinguível de uma regra inválida. A leitura correta segue o valor: qual dado entrou, em qual representação está agora, que transição ocorreu, qual parte pode observar a mudança e que informação será preservada caso algo dê errado.`,
    `O mecanismo concreto deste capítulo é: ${chapter.mechanism} Essa regra não deve ficar decorada como trivia de runtime. Ela determina onde try/catch alcança uma falha, quando um callback pode vencer outro, que objeto ainda está vivo e se o sistema pode assumir que um efeito foi concluído. Sempre conecte esse mecanismo a uma decisão observável, como rejeitar comando repetido, liberar recurso, atualizar foco ou limitar trabalho simultâneo.`,
    chapter.editorial[order - 1],
    `Um incidente característico é ${chapter.incident} Esse incidente não se resolve com mais um catch genérico. É necessário identificar se a falha é conhecida, se a operação pode ser repetida, qual estado já foi persistido e qual causa deve chegar ao log. A resposta correta muda conforme a fronteira, mas omitir essa pergunta torna o sistema otimista demais justamente quando a rede, o usuário ou o tempo deixam de cooperar.`,
    `A seção “${slot}” exige prever a sequência antes de executar. Escreva uma entrada normal, uma entrada de borda, uma entrada repetida e uma entrada atrasada; então diga qual resultado, erro ou cancelamento é permitido em cada caso. Esse exercício evita confundir caminho feliz com contrato. JavaScript oferece atalhos de sintaxe, mas não inventa a política: uma Promise rejeitada precisa de fronteira que a observe; uma operação repetida precisa de chave ou estado que preserve idempotência; um callback atrasado precisa de ciclo de vida. Sem essas decisões, o programa pode parecer correto em demonstração e falhar sob interação real.`,
    `Há uma diferença importante entre recuperar e esconder falha. Recuperar significa registrar contexto, preservar causa quando ela importa e colocar o sistema em próximo estado conhecido: pendente, cancelado, repetível ou bloqueado. Esconder significa converter qualquer exceção em valor vazio e deixar o chamador continuar sem saber o que ocorreu. A segunda opção é especialmente perigosa quando há efeito externo: cobrança, reserva, escrita ou evento podem ter ocorrido apesar do timeout. Portanto a fronteira precisa modelar incerteza, e não somente tentar novamente. O usuário merece mensagem clara; o operador precisa de evidência; a regra de domínio precisa permanecer consistente.`,
    `A escolha de dados determina o custo de manutenção. Estado derivado não deve competir com sua fonte de verdade; referências compartilhadas devem ter owner; recursos longos devem ter cleanup; e a ordem de execução precisa ser representada em vez de inferida por timing acidental. Em código de interface, isso inclui foco, listener e atualização de tela. Em código de servidor, inclui abort, timeout, transação e observabilidade. O mesmo princípio aparece em todos os ambientes: quem inicia uma operação também precisa saber como ela termina, como ela falha e como impedir que resultado antigo sobrescreva decisão nova.`,
    `O teste mais útil para ${topic} não confirma uma implementação interna; ele confirma efeito observável e fronteira. Use fake para relógio, rede ou armazenamento quando isso torna o cenário determinístico, mas não use mock para repetir a própria lógica que quer provar. Verifique ordem quando a ordem é requisito; verifique ausência de chamada quando um guard falha; verifique causa quando erro é traduzido; verifique que cleanup ocorre até sob exceção. Uma cobertura alta sem esses cenários mede execução de linha, não a segurança da decisão.`,
    `O experimento prático deste capítulo é ${chapter.experiment} Execute-o primeiro em exemplo mínimo e depois conecte-o a um caso de produto. A diferença entre os dois mostra se você entendeu a semântica da linguagem ou apenas fez o snippet funcionar. O resultado precisa ser registrado como asserção, métrica ou estado de interface, nunca apenas observado manualmente uma vez.`,
    `Em produção, o problema raramente chega com nome de capítulo. Ele aparece como tela travada, pedido duplicado, evento que não some, memória crescendo ou resultado que muda de ordem. O modelo mental de ${topic} permite reduzir o incidente a perguntas concretas: há operação pendente? qual valor venceu? quem ainda referencia esse objeto? existe limite de concorrência? a transição foi atômica onde precisava? Logs estruturados, métricas e teste de regressão transformam essas perguntas em evidência, em vez de tentativa aleatória de corrigir sintoma.`,
    `A extensão saudável preserva a mesma fronteira. Se uma nova política chega, injete-a; se um novo canal chega, adapte-o na borda; se um novo estado chega, inclua-o na transição e nos testes; se uma operação fica pesada, meça e mova trabalho sem esconder sua assinatura. Evite espalhar flags e callbacks porque isso cria segundo sistema de regras. Uma API pequena, um estado explícito e uma função que faz uma transição nomeável dão mais espaço para evoluir do que um atalho aparentemente genérico.`,
    `Ao terminar, você deve conseguir explicar ${topic} para outra pessoa sem citar uma biblioteca: qual invariante protege, qual operação pode falhar, qual resultado é descartado, qual recurso precisa ser liberado e onde o teste prova isso. Essa explicação é a densidade que torna uma apostila útil para manutenção: ela não entrega snippet decorado; entrega um modelo para modificar o sistema com segurança quando o contexto muda.`,
  ].join("\n\n") };
}

function examples(chapter: Chapter): [string, string] {
  switch (chapter.title) {
    case "Erros e contratos assíncronos":
      return [
        `class DomainError extends Error {\n  constructor(message, { cause, code }) {\n    super(message, { cause });\n    this.code = code;\n  }\n}\n\nasync function charge(gateway, command, signal) {\n  try { return await gateway.charge(command, { signal }); }\n  catch (cause) { throw new DomainError("Pagamento não confirmado", { cause, code: "PAYMENT_UNKNOWN" }); }\n}`,
        `async function reserve(api, idempotencyKey, signal) {\n  const response = await fetch("/reservations", {\n    method: "POST", signal, headers: { "Idempotency-Key": idempotencyKey },\n  });\n  if (!response.ok) throw new Error(\`reserva falhou: \${response.status}\`);\n  return response.json();\n}`,
      ];
    case "Event loop, microtasks e coordenação":
      return [
        `console.log("A");\nsetTimeout(() => console.log("task"), 0);\nPromise.resolve().then(() => console.log("microtask"));\nconsole.log("B");\n// A, B, microtask, task`,
        `async function pool(items, limit, worker) {\n  const pending = new Set();\n  for (const item of items) {\n    const job = Promise.resolve().then(() => worker(item));\n    pending.add(job); job.finally(() => pending.delete(job));\n    if (pending.size >= limit) await Promise.race(pending);\n  }\n  return Promise.all(pending);\n}`,
      ];
    case "DOM, eventos e acessibilidade":
      return [
        `const list = document.querySelector("[data-cart]");\nfunction onCartClick(event) {\n  const button = event.target.closest("button[data-remove]");\n  if (!button || !list.contains(button)) return;\n  removeLine(button.dataset.remove);\n}\nlist.addEventListener("click", onCartClick);\n// no unmount: list.removeEventListener("click", onCartClick);`,
        `function showError(input, message) {\n  const error = document.querySelector(\`#\${input.id}-error\`);\n  error.textContent = message;\n  input.setAttribute("aria-invalid", "true");\n  input.setAttribute("aria-describedby", error.id);\n  input.focus();\n}`,
      ];
    case "Classes, políticas e evolução de domínio":
      return [
        `class Wallet {\n  #balance = 0;\n  credit(amount) {\n    if (!Number.isSafeInteger(amount) || amount <= 0) throw new RangeError("crédito inválido");\n    this.#balance += amount;\n  }\n  snapshot() { return { balance: this.#balance }; }\n}`,
        `function priceFor(policy, cart) { return policy.calculate(cart); }\nconst memberPolicy = { calculate: (cart) => Math.round(cart.subtotal * 0.9) };\nconst dto = { balance: 250 };\nconst wallet = Object.assign(new Wallet(), dto); // não use: burla a invariável\n// prefira Wallet.fromDTO(dto) validando cada campo.`,
      ];
    case "Iteração, generators e streams":
      return [
        `function* chunks(values, size) {\n  for (let start = 0; start < values.length; start += size) {\n    yield values.slice(start, start + size);\n  }\n}\nfor (const batch of chunks(ids, 100)) await persist(batch);`,
        `async function* lines(stream) {\n  let rest = "";\n  for await (const chunk of stream) {\n    const parts = (rest + chunk).split("\\n");\n    rest = parts.pop() ?? "";\n    yield* parts;\n  }\n  if (rest) yield rest;\n}`,
      ];
    case "Performance, memória e profiling":
      return [
        `const byId = new Map(products.map((product) => [product.id, product]));\nfunction lineTotal(lines) {\n  return lines.reduce((sum, line) => sum + byId.get(line.id).price * line.quantity, 0);\n}\n// medir antes: trocar find repetido por Map só faz sentido sob carga real.`,
        `function bindResize(view) {\n  const controller = new AbortController();\n  window.addEventListener("resize", view.relayout, { signal: controller.signal });\n  return () => controller.abort();\n}\n// o cleanup remove a referência que manteria view viva após navegar.`,
      ];
    case "Testes, contratos e fronteiras":
      return [
        `import { expect, it } from "vitest";\nit("rejeita quantidade inválida e preserva total", () => {\n  for (const quantity of [-10, -1, 0]) {\n    expect(() => createLine({ price: 100, quantity })).toThrow("quantidade");\n  }\n  expect(createLine({ price: 100, quantity: 1 }).total).toBe(100);\n});`,
        `function fakeClock(at) { return { now: () => at }; }\nit("expira reserva no relógio controlado", () => {\n  const reservation = reserve(item, fakeClock("2026-08-24T10:00:00Z"));\n  expect(reservation.expiresAt).toBe("2026-08-24T10:15:00Z");\n});`,
      ];
    default:
      return [
        `function reducer(state, event) {\n  switch (event.type) {\n    case "reserve":\n      if (state.stock < event.quantity) return { ...state, error: "out_of_stock" };\n      return { ...state, stock: state.stock - event.quantity, history: [...state.history, event] };\n    default: return state;\n  }\n}`,
        `function applyIfCurrent(store, version, event) {\n  if (store.version !== version) return { ok: false, reason: "stale_version" };\n  const next = reducer(store.state, event);\n  return { ok: true, version: version + 1, state: next };\n}`,
      ];
  }
}

function blocks(chapter: Chapter, concept: string, order: number): Block[] {
  const [firstExample, secondExample] = examples(chapter);
  return [
    dense(chapter, concept, ["modelo mental", "implementação", "fronteiras", "como estender"][order - 1], order),
    { kind: "code", lang: "javascript", code: firstExample, caption: `Exemplo concreto: ${concept}` },
    { kind: "code", lang: "javascript", code: secondExample, caption: `Fronteira concreta: ${chapter.title}` },
    { kind: "porque", md: `A decisão relacionada a ${concept} precisa ser explícita porque ela define quem possui estado, qual resultado é válido e onde uma falha pode ser recuperada sem violar a regra de negócio.` },
    { kind: "quebraria", md: `Em produção, tratar ${concept} como detalhe de implementação permite que resultado atrasado, repetição ou estado compartilhado vença uma transição válida. A defesa é contrato de entrada, estado explícito, teste de borda e cleanup do recurso iniciado.` },
  ];
}

